import{_ as r,o as t,c as s,a2 as i}from"./chunks/framework.YT-FC_Xx.js";const p=JSON.parse('{"title":"节点组与订阅源","description":"","frontmatter":{},"headers":[],"relativePath":"guide/subscription-sources.md","filePath":"guide/subscription-sources.md","lastUpdated":1793146372000}'),n={name:"guide/subscription-sources.md"};function e(l,o,a,g,c,u){return t(),s("div",null,[...o[0]||(o[0]=[i('<h1 id="节点组与订阅源" tabindex="-1">节点组与订阅源 <a class="header-anchor" href="#节点组与订阅源" aria-label="Permalink to &quot;节点组与订阅源&quot;">​</a></h1><p>订阅里的节点来自 <strong>节点组</strong>（类似 Sub-Store 的组合订阅）：在订阅页切到 <strong>节点组</strong> 标签新建，选好来源、设好处理，再在订阅的“节点”页选用。机场或别人的订阅可以先添加成 <strong>订阅源</strong>，再选进节点组。</p><h2 id="节点组" tabindex="-1">节点组 <a class="header-anchor" href="#节点组" aria-label="Permalink to &quot;节点组&quot;">​</a></h2><p>编辑节点组分成 <strong>来源 / 处理 / 预览</strong> 三页：</p><ul><li><strong>来源</strong>：这个组包含哪些节点 <ul><li><strong>全部节点</strong>：包括以后新增的节点和订阅源，不用再回来勾选</li><li><strong>指定节点</strong>：只勾选需要的，分“自建”“导入”和“订阅源”三组。订阅源按整个源勾选，以后更新进来的节点会自动跟上；只要其中一部分可以用处理里的筛选</li></ul></li><li><strong>处理</strong>：<a href="./subscription-nodes">筛选、命名和 JS 脚本</a></li><li><strong>预览</strong>：这个组最终有哪些节点、改名前后的名字、过滤掉了几个</li></ul><p>节点的中转线路会跟着它一起出现在组里。</p><ul><li>一个订阅可以选多个节点组，按订阅里排的顺序依次输出；同一个节点在几个组里都有时会出现多次，可以用各组的筛选、前缀区分</li><li>节点组列表可以上下调整顺序，新建订阅默认选第一个“全部节点”的组</li><li>节点组改动对所有选用它的订阅立即生效；分给别人的订阅，凭据也会跟着下发到新加入节点所在的服务器</li><li>有订阅在用的节点组不能删除，先在订阅里取消选择</li></ul><h2 id="订阅源" tabindex="-1">订阅源 <a class="header-anchor" href="#订阅源" aria-label="Permalink to &quot;订阅源&quot;">​</a></h2><p>在 <strong>节点 → 订阅源</strong> 添加机场或别人的订阅链接，相当于 Sub-Store 的远程订阅；拿不到链接时也可以 <strong>上传订阅文件</strong>。也可以在 <strong>节点 → 更多 → 导入节点</strong> 里粘贴订阅地址或选择文件，打开 <strong>定时同步</strong> / <strong>存为订阅源</strong>（默认打开）就会存成订阅源；关掉则只导入一次：</p><ul><li>添加后立即拉取一次，节点出现在 <strong>节点</strong> 页“订阅源 · 名称”分组里，可以和其他导入节点一样检测、接中转、放进订阅</li><li><strong>自动更新</strong>：手动 / 6 小时 / 12 小时 / 每天。也可以点卡片右边的按钮立即更新</li><li><strong>上传文件</strong>：支持 Base64 订阅、分享链接、Clash / Mihomo 配置、sing-box 配置、Surge / Loon 节点行，最大 5MB。文件源不会自动更新，点卡片右边的上传按钮重新选文件即可，节点按下面的规则对上</li><li>更新时按 <strong>名称</strong> 对上已有节点（名称变了再按地址对）：地址变了就跟着改，挂在上面的中转也会改到新地址；订阅里没有了就删除，但挂着中转的会保留，免得中转断掉</li><li>在 <strong>编辑</strong> 里改过名的节点，更新后保留你起的名字；没改过的跟着订阅里的名称变</li><li>拉取失败或返回空内容时保留现有节点，卡片上显示错误</li><li>若部分节点解析或写入失败，或超过单次 500 个节点的处理上限，本次仍会更新可用节点，但不会删除未匹配的旧节点，并显示“订阅未完整同步”。修复订阅内容后再次更新，已有节点及节点组引用会继续保留；完整同步成功后才按正常规则移除来源中已删除的节点</li><li><strong>User-Agent</strong>（可选）：拉取时默认以 <code>clash.meta/1.19.0</code> 的身份请求，大多数机场会返回带全部参数的 Clash 配置。有的机场按 UA 决定返回的格式或节点（比如只给某些客户端下发 Reality、Hysteria2 节点），拿不到节点或缺节点时，在编辑订阅源里换成客户端的 UA，如 <code>mihomo/1.19.0</code>、<code>Shadowrocket/2070</code>；改了 UA 保存时会立即重新拉取</li><li>订阅源、网址模板和图标库默认不能从内网地址（127.0.0.1、10.x、192.168.x 等）下载，避免面板被用来读取内网服务。同机或局域网里跑着 Sub-Store 这类服务时，在 <strong>设置 → 安全与登录</strong> 打开 <strong>拉取订阅可访问内网地址</strong>；169.254.x 这类链路本地地址（云服务器元数据）始终不允许</li><li>机场返回的流量和到期信息（<code>Subscription-Userinfo</code>）会显示在卡片上</li><li><strong>用途</strong>：普通节点 / 中转（前置）/ 落地。机场节点通常拿来做前置：设成 <strong>中转</strong> 后，新建订阅会自动打开 <a href="./subscription-rules#链式代理">链式代理</a>，整个源作为中转、自建节点作为落地，机场节点改名、增删都会自动跟上（订阅选的节点组里要包含这个订阅源）</li><li><strong>只通过我的转发访问</strong>：新加进来的节点不直接进订阅，只通过你自己机器上的转发（中转线路）连接</li><li>删除订阅源时可以选连同节点一起删除，或只删订阅源、节点留下变成普通的导入节点</li></ul><p>典型用法：建一个节点组，选“指定节点”，勾上自己的节点和机场订阅源，再 <a href="./subscription-nodes">筛选地区、加国旗和排序</a>；订阅选这个组，一个链接全搞定。</p>',11)])])}const h=r(n,[["render",e]]);export{p as __pageData,h as default};
